INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Leto', 'Atréides', 'Duc de la Maison Atréides, noble honorable', 'Duc juste et pragmatique, entouré des meilleurs conseillers de l''Imperium. Sa popularité au Landsraad inquiète l''Empereur ; il accepte le fief d''Arrakis en sachant que c''est un piège.', '["Majeur", "Atréides"]', 'Livre de base', 242, '{"rank":"major","competences":[{"key":"analyse","rang":6,"specialisations":["Politique des Maisons","Politique impériale"]},{"key":"combat","rang":6,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Sang-froid"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Charme","Diplomatie","Empathie"]}],"principes":[{"key":"devoir","rang":8,"maxime":"Ma Maison, ma famille et mon peuple ne font qu''un."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":7,"maxime":"La loi doit gouverner le peuple, mais le cœur doit gouverner la loi."},{"key":"verite","rang":6,"maxime":"Le courage consiste aussi à étendre nos connaissances."}],"drive":null,"traits":["Noble","Juste et honorable"],"talents":[{"name":"Soutien","text":"Leto peut dépenser 2 points de Menace pour permettre à un allié de relancer sa réserve de dés. L''allié peut utiliser la Discipline de Leto à la place de sa compétence."},{"name":"Impérieux","text":"Une fois par scène, Leto peut accorder une action supplémentaire à un allié pendant son tour."},{"name":"Vibrant discours","text":"Quand Leto réussit un test de Rhétorique pour s''adresser à un groupe, il désigne parmi l''auditoire un nombre de personnes égal à sa Rhétorique. Elles peuvent relancer un d20 lors de leur prochain test qui correspond au principe utilisé pour ce test de Rhétorique."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Atréides' AND COALESCE(prenom, '') = 'Leto' AND COALESCE(source, '') = 'Livre de base');

