INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Paul', 'Atréides', 'Héritier de la Maison Atréides, Kwisatz Haderach en devenir', 'Fils unique du duc Leto et de dame Jessica, quinze ans, formé par Duncan Idaho, Gurney Halleck, Thufir Hawat et par sa mère aux voies du Bene Gesserit. Il fait des rêves troublants d''un avenir dont il serait seul à décider.', '["Majeur", "Atréides"]', 'Livre de base', 244, '{"rank":"major","competences":[{"key":"analyse","rang":6,"specialisations":["Politique impériale"]},{"key":"combat","rang":6,"specialisations":["Combat au bouclier","Lames courtes"]},{"key":"discipline","rang":6,"specialisations":["Précision","Maîtrise de soi"]},{"key":"mobilite","rang":5,"specialisations":["Contrôle du corps"]},{"key":"rhetorique","rang":5,"specialisations":["Charme"]}],"principes":[{"key":"devoir","rang":6,"maxime":"Le peuple est la vraie force d''une Grande Maison."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Je dois apprendre vite pour être digne de l''héritage de mon père."},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":8,"maxime":"Il existe dans cet univers des problèmes qui n''ont pas de réponse."}],"drive":null,"traits":["Héritier noble","Sage pour son âge","Promis à un grand destin"],"talents":[{"name":"Le calme dans la tempête (Combat)","text":"Paul peut réussir automatiquement un test de Combat en dépensant 3 points de Menace (1 Détermination)."},{"name":"Impérieux","text":"Une fois par scène, Paul peut accorder une action supplémentaire à un allié pendant son tour."},{"name":"Entraînement prana-bindu","text":"Paul peut relancer 1d20 lors d''un test de Mobilité ou de Discipline."},{"name":"La lame lente","text":"Paul peut ignorer un atout ennemi lors d''un duel ou d''une escarmouche quand il achète des dés supplémentaires avec de la Menace en attaquant."},{"name":"Voix","text":"Paul peut dépenser jusqu''à 3 points de Menace pour acheter autant de réussites automatiques sur un test de Rhétorique (1 réussite par point)."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Atréides' AND COALESCE(prenom, '') = 'Paul' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Gurney', 'Halleck', 'Maître de guerre de la Maison Atréides, guerrier troubadour', 'Évadé des fosses d''esclaves de Giedi Prime, il voue aux Atréides une loyauté sans faille et aux Harkonnen une haine tenace. Combattant redouté et joueur de balisette, il est le mentor et l''ami du jeune Paul.', '["Majeur", "Atréides"]', 'Livre de base', 246, '{"rank":"major","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":8,"specialisations":["Lames courtes","Tactique"]},{"key":"discipline","rang":7,"specialisations":["Résolution"]},{"key":"mobilite","rang":6,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Musique (balisette)"]}],"principes":[{"key":"devoir","rang":8,"maxime":"Les Atréides m''ont tout donné, je leur rendrai la pareille."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":7,"maxime":"Il n''y a de justice que celle que nous faisons nous-mêmes."},{"key":"verite","rang":6,"maxime":"La vérité est une chose complexe, mais on la reconnaît quand on la voit."}],"drive":null,"traits":["Guerrier","Jongleur"],"talents":[{"name":"Soutien","text":"Gurney peut dépenser 2 points de Menace pour permettre à un allié de relancer sa réserve de dés. L''allié peut utiliser la Discipline de Gurney à la place de sa compétence."},{"name":"Pourquoi je me bats (Devoir)","text":"Quand Gurney tente un test de Combat avec ce principe et que sa maxime correspond à l''action tentée, il peut relancer 1d20."},{"name":"La lame lente","text":"Gurney peut ignorer un atout ennemi lors d''un duel ou d''une escarmouche quand il achète des dés supplémentaires avec de la Menace en attaquant."},{"name":"Indéfectible loyauté","text":"Au début de chaque aventure, Gurney dispose d''une réserve de 3 points de Menace (1 Détermination) que lui seul peut utiliser, uniquement pour une action au service direct de la Maison Atréides."}],"atouts":[],"rolls":[]}'
