WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Idaho' AND COALESCE(prenom, '') = 'Duncan' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Wellington', 'Yueh', 'Médecin de la Maison Atréides, traître malgré lui', 'Docteur Suk de l''École intérieure, médecin apprécié et confident de la famille du Duc. Les Harkonnen détiennent sa femme Wanna et Piter de Vries a brisé son conditionnement impérial : il trahira ceux qu''il respecte le plus.', '["Majeur", "Atréides", "Docteur Suk"]', 'Livre de base', 249, '{"rank":"major","competences":[{"key":"analyse","rang":8,"specialisations":["Génétique","Chirurgie"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Duperie","Enseignement"]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Qui peut croire en une puissance supérieure quand le mal est inévitable ?"},{"key":"justice","rang":8,"maxime":"Ma conduite est terrible, mais je dois trouver un moyen de bien faire."},{"key":"verite","rang":6,"maxime":"Je ne sais plus ce qui est vrai, mais j''agirai malgré tout."}],"drive":null,"traits":["Docteur Suk","Méprise les Harkonnen"],"talents":[{"name":"Conseiller (Analyse)","text":"Yueh peut relancer un d20 de la réserve d''un allié qu''il assiste."},{"name":"Conditionnement Impérial","text":"Toute tentative de contraindre Yueh à faire du mal à un être humain échoue automatiquement, et il réussit automatiquement tout test visant à persuader quelqu''un qu''il ne lui veut aucun mal. Les tentatives des Harkonnen ne sont pas concernées : ils ont trouvé sa faiblesse, la sécurité de sa femme Wanna."},{"name":"Étude poussée","text":"Une fois par scène, Yueh peut utiliser sa compétence d''Analyse sur un test à la place de toute autre compétence ; il est considéré comme disposant d''une spécialisation pour ce test."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Yueh' AND COALESCE(prenom, '') = 'Wellington' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Vladimir', 'Harkonnen', 'Siridar-Baron de la Maison Harkonnen, noble retors', 'Obèse soutenu par des suspenseurs, cruel et vénal mais d''une intelligence subtile, il a hissé sa Maison au sommet et obtenu Arrakis. Il trame la chute des Atréides avec l''Empereur, avant de trahir ce dernier pour viser le trône.', '["Majeur", "Harkonnen"]', 'Livre de base', 251, '{"rank":"major","competences":[{"key":"analyse","rang":8,"specialisations":["Politique des Maisons","Politique impériale"]},{"key":"combat","rang":4,"specialisations":["Stratégie"]},{"key":"discipline","rang":6,"specialisations":["Espionnage"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je suis la Maison Harkonnen, et je ne dois loyauté qu''à ma Maison."},{"key":"domination","rang":8,"maxime":"Qu''y a-t-il d''autre dans la vie que la quête de sa propre puissance ?"},{"key":"foi","rang":6,"maxime":"La foi n''a de valeur que dans la mesure où elle permet de contrôler ses inférieurs."},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Noble","Rusé et cruel"],"talents":[{"name":"Promesse oblige","text":"Le Baron peut dépenser 1, 2 ou 3 points de Menace pour rendre un accord contraignant. Pour le rompre, l''adversaire doit dépenser le double en Impulsion."},{"name":"Toujours sur ses gardes","text":"Quand Le baron Harkonnen tente un test pour détecter un danger ou des ennemis cachés, la Difficulté diminue de 2 (minimum 0). De plus, une fois par scène, il peut augmenter de 2 le coût pour un adversaire de Garder l''initiative."},{"name":"Impérieux","text":"Une fois par scène, Le baron Harkonnen peut accorder une action supplémentaire à un allié pendant son tour."},{"name":"Discours roué","text":"Le baron Harkonnen peut créer un nouveau trait chaque fois qu''il dépense de la Menace pour acheter des dés supplémentaires sur un test de Rhétorique."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Harkonnen' AND COALESCE(prenom, '') = 'Vladimir' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Piter', 'de Vries', 'Mentat tordu de la Maison Harkonnen', 'Mentat « tordu » par le Bene Tleilax, sadique et brillant, confident du Baron qui le juge pourtant sacrifiable. Il a brisé le conditionnement Suk du docteur Yueh et dirige un réseau de renseignement redoutable.', '["Majeur", "Harkonnen", "Mentat"]', 'Livre de base', 252, '{"rank":"major","competences":[{"key":"analyse","rang":8,"specialisations":["Analyse de données","Politique des Maisons","Politique impériale"]},{"key":"combat","rang":5,"specialisations":["Assassinat"]},{"key":"discipline","rang":7,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je sers le Baron en toutes choses, mais je reste mon propre maître."},{"key":"domination","rang":8,"maxime":"La domination est la seule noble quête."},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":6,"maxime":"La vérité absolue est nécessaire pour forger une vérité plus utile."}],"drive":null,"traits":["Mentat tordu","Tueur"],"talents":[{"name":"Conseiller (Analyse)","text":"Piter peut relancer un d20 de la réserve d''un allié qu''il assiste."},{"name":"Déterminé","text":"Après avoir dépensé 3 points de Menace pour 1 point de Détermination, Piter lance 1d20. Sur un résultat inférieur ou égal à sa Discipline seule, il regagne immédiatement la Menace dépensée."},{"name":"Discipline mentat","text":"Piter ajoute deux réussites automatiques à tous les tests d''Analyse visant à se souvenir de faits ou de données."},{"name":"Mentat tordu","text":"Piter gagne 1 point de Menace bonus quand il ajoute de la Menace lors d''un test d''Analyse. Il ne peut l''utiliser que pour Obtenir des informations, ou pour créer un trait exploitant une faiblesse d''un adversaire ou lui causant douleur et souffrance."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'de Vries' AND COALESCE(prenom, '') = 'Piter' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Feyd-Rautha', 'Harkonnen', 'Neveu et héritier favori du Baron, élégant duelliste', 'Aussi beau que son oncle est repoussant, cruel même pour un Harkonnen, il a tué de nombreux esclaves dans l''arène, souvent avec des lames empoisonnées. Instruit par Piter de Vries, le Baron voit en lui l''héritier de son futur Empire.', '["Majeur", "Harkonnen"]', 'Livre de base', 253, '{"rank":"major","competences":[{"key":"analyse","rang":6,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames courtes"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":7,"specialisations":["Rapidité"]},{"key":"rhetorique","rang":6,"specialisations":["Intimidation","Écoute"]}],"principes":[{"key":"devoir","rang":6,"maxime":"Je sers la Maison parce qu''un jour elle sera mienne."},{"key":"domination","rang":8,"maxime":"Je mérite d''avoir tout ce que je veux."},{"key":"foi","rang":7,"maxime":"Je suis le meilleur dans tout ce que je fais."},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Duelliste","Arrogant et impitoyable"],"talents":[{"name":"La lame lente","text":"Feyd peut ignorer un atout ennemi lors d''un duel ou d''une escarmouche quand il achète des dés supplémentaires avec de la Menace en attaquant."},{"name":"Audacieux (Combat)","text":"Feyd peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Combat."},{"name":"Action décisive","text":"Après avoir éliminé un atout ennemi grâce au Combat, Feyd peut éliminer un second atout ennemi en dépensant 2 points de Menace."},{"name":"Manœuvre rapide","text":"Lors d''un test pour atteindre rapidement une destination, à pied ou en véhicule, Feyd réduit la Difficulté de 1. En conflit, quand il déplace un atout, il peut lui faire franchir une zone supplémentaire en dépensant 1 point de Menace."},{"name":"Pourquoi je me bats (Domination)","text":"Quand Feyd tente un test de Combat avec ce principe et que sa maxime correspond à l''action tentée, il peut relancer 1d20."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Harkonnen' AND COALESCE(prenom, '') = 'Feyd-Rautha' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Glossu', 'Rabban', '« La Bête », neveu du Baron et gouverneur d''Arrakis', 'Aîné des neveux du Baron, brute qui a tué son propre père, incapable de subtilité politique. Gouverneur d''Arrakis, il opprime la population et les Fremen, sans comprendre que le Baron le laisse faire pour que Feyd passe ensuite pour un sauveur.', '["Majeur", "Harkonnen"]', 'Livre de base', 254, '{"rank":"major","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Laser"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":5,"specialisations":["Intimidation"]}],"principes":[{"key":"devoir","rang":6,"maxime":"La peur maintient les subordonnés dans le rang."},{"key":"domination","rang":8,"maxime":"Je suis plus fort, donc je suis meilleur."},{"key":"foi","rang":7,"maxime":"Pas besoin de comprendre un plan pour savoir qu''il me profitera."},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Tyran brutal","Brutal et vicieux"],"talents":[{"name":"Audacieux (Combat)","text":"Rabban peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Combat."},{"name":"Célérité","text":"Rabban peut choisir de subir une complication supplémentaire lors d''un test de Mobilité pour obtenir une réussite automatique. Au cours d''un conflit, il peut dépenser 1 point de Menace pour agir en premier, quel que soit l''ordre normal."},{"name":"Maître d''armes","text":"Au début d''un duel, d''une escarmouche ou d''une bataille, Rabban peut dépenser 1 point de Menace pour augmenter de 1 la Qualité d''un de ses atouts martiaux pour la durée du conflit."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Rabban' AND COALESCE(prenom, '') = 'Glossu' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Shaddam IV', 'Corrino', 'Empereur Padishah de l''univers connu', '81e Empereur Padishah, père de cinq filles et sans héritier mâle, il intrigue sans cesse pour préserver l''héritage de sa Maison. Menacé par la popularité du duc Leto, il s''allie au baron Harkonnen, avec l''aide du comte Fenring, pour détruire les Atréides sans s''exposer.', '["Majeur", "Corrino"]', 'Livre de base', 256, '{"rank":"major","competences":[{"key":"analyse","rang":7,"specialisations":["Politique des Maisons","Politique impériale"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Commandement","Sang-froid"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"La couronne est lourde, mais elle est faite d''or."},{"key":"domination","rang":8,"maxime":"L''univers m''appartient."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":6,"maxime":"Les gens de moindre rang doivent s''en remettre à leurs supérieurs pour savoir ce qui est juste."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Empereur de l''univers connu","Comploteur paranoïaque"],"talents":[{"name":"Prudent (Rhétorique)","text":"L''Empereur peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Rhétorique."},{"name":"Collaboration (Analyse)","text":"L''Empereur peut dépenser 2 points de Menace pour permettre à un allié d''utiliser sa valeur de Analyse à la place de la sienne."},{"name":"Toujours sur ses gardes","text":"Quand L''Empereur tente un test pour détecter un danger ou des ennemis cachés, la Difficulté diminue de 2 (minimum 0). De plus, une fois par scène, il peut augmenter de 2 le coût pour un adversaire de Garder l''initiative."},{"name":"Contrôle rigoureux","text":"L''Empereur peut utiliser sa Discipline à la place de n''importe quelle compétence lors d''une tâche étendue. Si la compétence était déjà la Discipline, le PNJ gagne +1 aux conditions."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Corrino' AND COALESCE(prenom, '') = 'Shaddam IV' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Irulan', 'Corrino', 'Princesse impériale, héritière de l''Imperium', 'La plus belle et la plus perspicace des filles de Shaddam IV, élevée pour être un pion matrimonial. Fière, cultivée, passionnée d''histoire et de littérature, initiée du Bene Gesserit restée simple adepte, elle sait parfois déjouer son propre père.', '["Majeur", "Corrino", "Bene Gesserit"]', 'Livre de base', 257, '{"rank":"major","competences":[{"key":"analyse","rang":7,"specialisations":["Politique impériale"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":["Observation"]},{"key":"mobilite","rang":6,"specialisations":["Danse"]},{"key":"rhetorique","rang":6,"specialisations":["Charme"]}],"principes":[{"key":"devoir","rang":8,"maxime":"Mon destin a été façonné pour moi, mais je choisirai comment l''affronter."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":7,"maxime":""}],"drive":null,"traits":["Princesse","Érudite","Bene Gesserit"],"talents":[{"name":"Étude poussée","text":"Une fois par scène, Irulan peut utiliser sa compétence d''Analyse sur un test à la place de toute autre compétence ; elle est considéré comme disposant d''une spécialisation pour ce test."},{"name":"Le parfait sous-entendu","text":"Irulan peut dissimuler un message caché dans une conversation en augmentant de 1 la Difficulté du test de Rhétorique."},{"name":"Entraînement prana-bindu","text":"Irulan peut relancer 1d20 lors d''un test de Mobilité ou de Discipline."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Corrino' AND COALESCE(prenom, '') = 'Irulan' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Gaius Helen', 'Mohiam', 'Révérende Mère, Diseuse de Vérité de l''Empereur', 'Révérende Mère accomplie et maîtresse du prana-bindu, issue du programme génétique du Bene Gesserit, elle sert de Diseuse de Vérité à Shaddam IV. Sa loyauté va avant tout à la Communauté, pour laquelle elle est prête à tout.', '["Majeur", "Bene Gesserit", "Corrino"]', 'Livre de base', 258, '{"rank":"major","competences":[{"key":"analyse","rang":7,"specialisations":["Politique impériale"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Observation"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":8,"maxime":"Je connais ma place dans notre plan."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Le mystère de la vie n''est pas un problème à résoudre, mais une réalité à vivre."},{"key":"justice","rang":6,"maxime":"Chacun doit recevoir ce qu''il mérite."},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Bene Gesserit","Révérende Mère","Diseuse de Vérité"],"talents":[{"name":"Conseiller (Rhétorique)","text":"La Révérende Mère peut relancer un d20 de la réserve d''un allié qu''elle assiste."},{"name":"Le calme dans la tempête (Analyse)","text":"La Révérende Mère peut réussir automatiquement un test de Analyse en dépensant 3 points de Menace (1 Détermination)."},{"name":"Hyperacuité","text":"Chaque fois que la Révérende Mère dépense de la Menace pour Obtenir des informations, elle peut poser deux questions par point dépensé. De plus, les limites de ce que d''autres pourraient remarquer ne s''appliquent pas à elle."},{"name":"Mémoire seconde","text":"Grâce à ce talent, La Révérende Mère peut se souvenir de choses survenues des années avant sa naissance."},{"name":"Observation passive","text":"Quand la Révérende Mère entre dans une scène, elle peut poser une question au meneur comme si elle avait dépensé de la Menace pour Obtenir des informations."},{"name":"Entraînement prana-bindu","text":"La Révérende Mère peut relancer 1d20 lors d''un test de Mobilité ou de Discipline."},{"name":"Voix","text":"La Révérende Mère peut dépenser jusqu''à 3 points de Menace pour acheter autant de réussites automatiques sur un test de Rhétorique (1 réussite par point)."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Mohiam' AND COALESCE(prenom, '') = 'Gaius Helen' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Hasimir', 'Fenring', 'Comte, courtisan assassin et confident de l''Empereur', 'Cousin et seul véritable ami d''enfance de Shaddam IV, eunuque génétique à l''air inoffensif, il cultive ses tics de langage pour qu''on le sous-estime. Conseiller, émissaire et assassin présumé, il est Observateur impérial sur Arrakis.', '["Majeur", "Corrino"]', 'Livre de base', 259, '{"rank":"major","competences":[{"key":"analyse","rang":6,"specialisations":["Poisons"]},{"key":"combat","rang":7,"specialisations":["Assassinat"]},{"key":"discipline","rang":6,"specialisations":["Commandement"]},{"key":"mobilite","rang":8,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":6,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Ce qu''on attend de moi est la moindre de mes obligations."},{"key":"domination","rang":8,"maxime":"Je fais ce qui me plaît."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":6,"maxime":"La loi, c''est l''affaire des juristes et des victimes."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Noble courtisan","Assassin","Psychopathe"],"talents":[{"name":"Conseiller (Combat)","text":"Fenring peut relancer un d20 de la réserve d''un allié qu''il assiste."},{"name":"Intentions cachées","text":"Quand un adversaire rate un test d''Analyse ou de Rhétorique contre Fenring, le PNJ peut immédiatement créer un trait reflétant une idée erronée que cet adversaire se fait à son sujet."},{"name":"Observation passive","text":"Quand le comte Fenring entre dans une scène, il connaît une information cachée sur la situation ou les personnages joueurs, comme s''il avait dépensé de la Menace pour Obtenir des informations."},{"name":"À pas de loup","text":"Quand Fenring tente un test de Mobilité pour se faufiler à travers une zone, ou pour déplacer discrètement un atout au cours d''un conflit, le premier d20 supplémentaire acheté pour ce test est gratuit."},{"name":"Discours roué","text":"Fenring peut créer un nouveau trait chaque fois qu''il dépense de la Menace pour acheter des dés supplémentaires sur un test de Rhétorique."},{"name":"Combattre quelqu''un, c''est le connaître (Analyse)","text":"Fenring ajoute 2 points à la Menace quand le PNJ vainc un ennemi grâce à la compétence Analyse. Ces points peuvent servir à Obtenir des informations ou à créer un trait concernant cet ennemi."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Fenring' AND COALESCE(prenom, '') = 'Hasimir' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Stilgar', 'Naib du sietch Tabr', 'Chef respecté du sietch Tabr, sage, pragmatique et parfois intransigeant, sauvé jadis par Pardot Kynes. Profondément spirituel, il ne voit aucune contradiction entre les prophéties fremen et le rêve écologique des Kynes, et voue tout à la libération de son peuple.', '["Majeur", "Fremen"]', 'Livre de base', 260, '{"rank":"major","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames courtes"]},{"key":"discipline","rang":7,"specialisations":["Commandement"]},{"key":"mobilite","rang":6,"specialisations":["Chevaucheur de ver"]},{"key":"rhetorique","rang":5,"specialisations":["Intimidation"]}],"principes":[{"key":"devoir","rang":7,"maxime":"La vie de la tribu est ma propre vie."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":8,"maxime":"Shai-Hulud nous montre la voie."},{"key":"justice","rang":6,"maxime":"Un monde dur exige des lois dures, mais nous devons connaître la miséricorde sous toutes ses formes."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Chef fremen","Farouche et dévoué"],"talents":[{"name":"Prudent (Combat)","text":"Stilgar peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Combat."},{"name":"Le calme dans la tempête (Mobilité)","text":"Stilgar peut réussir automatiquement un test de Mobilité en dépensant 3 points de Menace (1 Détermination)."},{"name":"Geste délibéré","text":"Lors d''un test de Mobilité, Stilgar peut dépenser de la Menace pour ignorer tout ou partie des complications liées à la Mobilité, à raison de 1 point par complication ignorée."},{"name":"Contrôle rigoureux","text":"Stilgar peut utiliser sa Discipline à la place de n''importe quelle compétence lors d''une tâche étendue. Si la compétence était déjà la Discipline, le PNJ gagne +1 aux conditions."},{"name":"Combattre quelqu''un, c''est le connaître (Combat)","text":"Stilgar ajoute 2 points à la Menace quand le PNJ vainc un ennemi grâce à la compétence Combat. Ces points peuvent servir à Obtenir des informations ou à créer un trait concernant cet ennemi."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Stilgar' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Chani', 'Kynes', 'Guerrière fremen du sietch Tabr', 'Fille du planétologiste Liet Kynes et de la Fremen Faroula, chevaucheuse des sables et tueuse de Harkonnen malgré son jeune âge. Fervente, déjà en voie de devenir sayyadina, elle maîtrise le krys, la discrétion et l''embuscade.', '["Majeur", "Fremen"]', 'Livre de base', 261, '{"rank":"major","competences":[{"key":"analyse","rang":5,"specialisations":["Religion (Fremen)"]},{"key":"combat","rang":6,"specialisations":["Lames courtes"]},{"key":"discipline","rang":7,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":"Je ne suis qu''une Fremen, mais je leur dois tout comme ils me doivent tout."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":8,"maxime":"Les fidèles seront récompensés par une lutte qui les grandit."},{"key":"justice","rang":7,"maxime":"La justice et la foi sont indissociables."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Fremen","Guerrière"],"talents":[{"name":"Audacieux (Mobilité)","text":"Chani peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Mobilité."},{"name":"Geste délibéré","text":"Lors d''un test de Mobilité, Chani peut dépenser de la Menace pour ignorer tout ou partie des complications liées à la Mobilité, à raison de 1 point par complication ignorée."},{"name":"À pas de loup","text":"Quand Chani tente un test de Mobilité pour se faufiler à travers une zone, ou pour déplacer discrètement un atout au cours d''un conflit, le premier d20 supplémentaire acheté pour ce test est gratuit."},{"name":"Pourquoi je me bats (Foi)","text":"Quand Chani tente un test de Combat avec la Foi et que la maxime de ce principe correspond à l''action tentée, elle peut relancer 1d20."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Kynes' AND COALESCE(prenom, '') = 'Chani' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Liet', 'Kynes', 'Planétologiste impérial et Juge du Changement', 'Enfant de Pardot Kynes et d''une Fremen, héritier de son poste de planétologiste impérial, dévoué avant tout aux Fremen et au rêve d''un Arrakis verdoyant. Nommé Juge du Changement pour superviser la transition des Harkonnen aux Atréides, dont il n''attend pas grand-chose.', '["Majeur", "Fremen", "Imperium"]', 'Livre de base', 262, '{"rank":"major","competences":[{"key":"analyse","rang":7,"specialisations":["Botanique","Écologie"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Survie (désert)"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":"Je dois allégeance à l''Empereur, mais ma vie aux Fremen."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":8,"maxime":"Le désert fournira aux fidèles ce dont ils ont besoin."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":7,"maxime":"Les faits ne peuvent être cachés, seulement embrouillés."}],"drive":null,"traits":["Fremen","Planétologiste"],"talents":[{"name":"Prudent (Analyse)","text":"Kynes peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Analyse."},{"name":"Collaboration (Analyse)","text":"Kynes peut dépenser 2 points de Menace pour permettre à un allié d''utiliser sa valeur de Analyse à la place de la sienne."},{"name":"Indéfectible loyauté (Fremen)","text":"Au début de chaque aventure, Liet Kynes dispose d''une réserve de 3 points de Menace que Kynes seul peut utiliser, uniquement pour une action au service direct des Fremen."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Kynes' AND COALESCE(prenom, '') = 'Liet' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Natif d''Arrakeen', 'Artisan pyon d''Arrakeen', 'Les natifs d''Arrakeen, les « pyons » des Faufreluches, vivent de métiers variés hors des Maisons nobles et du crime organisé. Artisans qualifiés, ils sont parfois appelés par les nobles pour des travaux spécialisés ; certains espèrent être embauchés, d''autres revendent des informations au plus offrant.', '["Notable", "Archétype"]', 'Livre de base', 271, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":["Technologie avancée"]},{"key":"combat","rang":3,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Sang-froid","Précision"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":"Le travail et le talent mènent à l''avancement."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Roturier"],"talents":[{"name":"Le calme dans la tempête (Discipline)","text":"Le PNJ peut réussir automatiquement un test de Discipline en dépensant 3 points de Menace (1 Détermination)."}],"atouts":[{"name":"Outils de métier","quality":null},{"name":"Atelier","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Natif d''Arrakeen' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Assassin', 'Tueur professionnel au service d''une Maison', 'Professionnels reconnus par la Grande Convention, les assassins éliminent les rivaux de leurs employeurs selon les règles du Manuel des Assassins, souvent par poison ou chercheur-tueur. Entre deux missions, ils conseillent leur Maison et connaissent intimement les rouages du Landsraad.', '["Notable", "Archétype"]', 'Livre de base', 272, '{"rank":"notable","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Assassinat","Attaques sournoises"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":7,"maxime":"La mort décide de qui gouverne."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Assassin","Conseiller d''une Grande Maison"],"talents":[{"name":"Maître d''armes","text":"Au début d''un duel, d''une escarmouche ou d''une bataille, Le PNJ peut dépenser 1 point de Menace pour augmenter de 1 la Qualité d''un de ses atouts martiaux pour la durée du conflit."}],"atouts":[{"name":"Pistolet à aiguilles","quality":null},{"name":"Chercheur-tueur","quality":null},{"name":"Poison","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Assassin' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Agent du Bene Gesserit', 'Sœur ou acolyte infiltrée du Bene Gesserit', 'Sœurs ou acolytes présentes dans tout l''Imperium, elles recueillent des informations et servent les desseins de l''Ordre sous une apparente neutralité. Observation aiguë, conditionnement prana-bindu et maîtrise de la Voix en font des adversaires redoutables.', '["Notable", "Archétype", "Bene Gesserit"]', 'Livre de base', 273, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Sang-froid","Espionnage"]},{"key":"mobilite","rang":6,"specialisations":["Contrôle du corps"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je connais mes responsabilités."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Bene Gesserit"],"talents":[{"name":"Entraînement prana-bindu","text":"Le PNJ peut relancer 1d20 lors d''un test de Mobilité ou de Discipline."},{"name":"Hyperacuité","text":"Chaque fois que le PNJ dépense de la Menace pour Obtenir des informations, il apprend deux informations cachées par point dépensé. De plus, les limites de ce que d''autres pourraient remarquer ne s''appliquent pas à lui."}],"atouts":[{"name":"Dague dissimulable","quality":null},{"name":"Perforations codées Bene Gesserit","quality":null},{"name":"Film minimic (vierge)","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Agent du Bene Gesserit' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Révérende Mère du Bene Gesserit', 'Révérende Mère, conseillère et Diseuse de Vérité', 'Ayant survécu à l''Agonie, elles accèdent à la Mémoire seconde de leurs ancêtres et détectent le mensonge. Conseillères redoutées, elles manipulent le Landsraad depuis Wallach IX dans leur quête du Kwisatz Haderach.', '["Notable", "Archétype", "Bene Gesserit"]', 'Livre de base', 274, '{"rank":"notable","competences":[{"key":"analyse","rang":8,"specialisations":["Savoir des factions (Bene Gesserit)"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Commandement","Sang-froid"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"La Communauté l''emportera."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":6,"maxime":""}],"drive":null,"traits":["Bene Gesserit","Révérende Mère"],"talents":[{"name":"Hyperacuité","text":"Chaque fois que la Révérende Mère dépense de la Menace pour Obtenir des informations, elle apprend deux informations par point dépensé. De plus, les limites de ce que d''autres pourraient remarquer ne s''appliquent pas à elle."},{"name":"Mémoire seconde","text":"Grâce à ce talent, La Révérende Mère peut se souvenir de choses survenues des années avant sa naissance."},{"name":"Entraînement prana-bindu","text":"La Révérende Mère peut relancer 1d20 lors d''un test de Mobilité ou de Discipline."},{"name":"Voix","text":"La Révérende Mère peut dépenser jusqu''à 3 points de Menace (1 Détermination) pour acheter autant de réussites automatiques sur un test de Rhétorique (1 réussite par point)."}],"atouts":[{"name":"Secret dangereux","quality":null},{"name":"Groupe d''acolytes du Bene Gesserit","quality":null},{"name":"Robes de Révérende Mère","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Révérende Mère du Bene Gesserit' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Criminel', 'Malfrat des bas-fonds', 'Partout où il y a des lois, quelqu''un cherche à profiter de leur violation, et Arrakis ne fait pas exception. Loin des résidences nobles, pickpockets, racketteurs, cambrioleurs, kidnappeurs et incendiaires prospèrent.', '["Notable", "Archétype"]', 'Livre de base', 275, '{"rank":"notable","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":6,"specialisations":["Combat déloyal","Esquive"]},{"key":"discipline","rang":4,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":7,"maxime":"Je prends ce dont j''ai besoin."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Roturier","Hors-la-loi"],"talents":[{"name":"Célérité","text":"Le PNJ peut choisir de subir une complication supplémentaire lors d''un test de Mobilité pour obtenir une réussite automatique. Au cours d''un conflit, il peut dépenser 1 point de Menace pour agir en premier, quel que soit l''ordre normal."}],"atouts":[{"name":"Corde en fibre de krimskell","quality":null},{"name":"Pistolet maula","quality":null},{"name":"Petite bande","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Criminel' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Courtisan', 'Intrigant des cours nobles', 'Héritiers de Maisons mineures ou de fortunes marchandes, les courtisans se disputent influence et pouvoir autour du mélange. Dans les banquets où les rumeurs vont plus vite que les plats, ils gravissent l''échelle sociale sans se soucier de qui ils piétinent.', '["Notable", "Archétype"]', 'Livre de base', 276, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Espionnage"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Charme","Commérages"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":""},{"key":"foi","rang":6,"maxime":"Arrakis a besoin de la classe dirigeante."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Courtisan","Aristocrate"],"talents":[{"name":"Masque du pouvoir","text":"Une fois par scène, Le PNJ peut créer gratuitement un atout temporaire d''intrigue ou d''espionnage qui lui permet de lancer un conflit d''intrigue ou d''espionnage. En cas d''échec, le bluff est éventé et le PNJ subit une complication."}],"atouts":[{"name":"Dard","quality":null},{"name":"Véhicule terrestre","quality":null},{"name":"Manoir","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Courtisan' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Émissaire', 'Messager et négociateur d''une Maison', 'Envoyer un messager à bord d''un vaisseau de la Guilde est plus rapide qu''un signal entre les étoiles : les émissaires mémorisent ou transportent les messages et disposent d''une grande latitude pour atteindre le but fixé. Pour eux, l''échec est souvent fatal.', '["Notable", "Archétype"]', 'Livre de base', 277, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Étiquette"]},{"key":"combat","rang":3,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Charme","Diplomatie"]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":7,"maxime":"Le message est ce qui compte."}],"drive":null,"traits":["Diplomate","Voyageur"],"talents":[{"name":"Promesse oblige","text":"Le PNJ peut dépenser 1, 2 ou 3 points de Menace pour rendre un accord contraignant. Pour le rompre, l''adversaire doit dépenser le double en Impulsion."}],"atouts":[{"name":"Clé de chiffrement","quality":null},{"name":"Tenue élégante","quality":null},{"name":"Agents locaux de sa Maison","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Émissaire' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Danseur-Visage', 'Imitateur tleilaxu', 'Conçus à l''origine comme artistes, les Danseurs-Visages peuvent imiter n''importe qui et font des infiltrateurs d''une efficacité redoutable, quoique coûteux. Beaucoup soupçonnent les Tleilaxu de s''en servir pour leurs propres desseins.', '["Notable", "Archétype", "Bene Tleilax"]', 'Livre de base', 278, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Contrôle du corps"]},{"key":"rhetorique","rang":7,"specialisations":["Comédie","Déguisement"]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"L''univers est aussi inconstant que moi."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Imposteur"],"talents":[{"name":"Entraînement prana-bindu","text":"Le PNJ peut relancer 1d20 lors d''un test de Mobilité ou de Discipline."},{"name":"Danse-Visage","text":"Le PNJ ne subit aucune pénalité pour se déguiser, que ce soit pour paraître jeune ou vieux, homme ou femme, ou sous les traits d''une personne précise."}],"atouts":[],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Danseur-Visage' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ancien fremen', 'Sage du désert profond', 'Rarement vus en ville, ces anciens mystérieux préfèrent le désert profond. Longtemps persécutés par les Harkonnen, ils se méfient des étrangers et méprisent les pyons d''Arrakeen, mais sont des puits de savoir sur le désert, ses usages et le mélange.', '["Notable", "Archétype", "Fremen"]', 'Livre de base', 279, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Tactique","Lames courtes"]},{"key":"discipline","rang":8,"specialisations":["Survie (désert)"]},{"key":"mobilite","rang":6,"specialisations":["Chevaucheur de ver"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Arrakis sera transformé."},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Fremen"],"talents":[{"name":"Promesse oblige","text":"Le PNJ peut dépenser 1, 2 ou 3 points de Menace pour rendre un accord contraignant. Pour le rompre, l''adversaire doit dépenser le double en Impulsion."},{"name":"Prudent (Discipline)","text":"Le PNJ peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Discipline."},{"name":"Ténacité (Combat)","text":"Le PNJ peut Résister à la défaite deux fois par scène lors d''un conflit utilisant la compétence Combat."}],"atouts":[{"name":"Krys","quality":null},{"name":"Hameçons à Faiseur","quality":null},{"name":"Petite bande de guerriers fremen","quality":null},{"name":"Distille","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ancien fremen' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Guerrier fremen', 'Combattant fremen, parfois Fedaykin', 'Forgés par le désert comme les Sardaukar par Salusa Secundus, les guerriers fremen aux yeux bleu sur bleu portent distille et krys, chevauchent les vers et tendent des embuscades avant de disparaître sans laisser de trace.', '["Notable", "Archétype", "Fremen"]', 'Livre de base', 280, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":8,"specialisations":["Duel","Lames courtes","Combat à mains nues"]},{"key":"discipline","rang":7,"specialisations":["Survie (désert)","Résolution"]},{"key":"mobilite","rang":7,"specialisations":["Chevaucheur de ver"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Le sietch avant tout le reste."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":8,"maxime":""},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Fremen"],"talents":[{"name":"Action décisive","text":"Après avoir éliminé un atout ennemi grâce au Combat, Le PNJ peut éliminer un second atout ennemi en dépensant 2 points de Menace."},{"name":"Agile","text":"Lors d''un test de Mobilité en terrain difficile, Le PNJ réduit la Difficulté de 2. Si elle tombe à 0, le PNJ franchit ou contourne librement l''obstacle."},{"name":"Ténacité (Combat)","text":"Le PNJ peut Résister à la défaite deux fois par scène lors d''un conflit utilisant la compétence Combat."}],"atouts":[{"name":"Krys","quality":null},{"name":"Fremkit","quality":null},{"name":"Distille","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Guerrier fremen' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Agent de la Guilde', 'Représentant discret de la Guilde spatiale', 'Les Navigateurs ne quittant guère leurs cuves, la Guilde traite ses affaires par des agents présents partout où l''on organise un transport interplanétaire. Ils se fondent dans leur environnement et cachent souvent leurs yeux entièrement bleus.', '["Notable", "Archétype", "Guilde spatiale"]', 'Livre de base', 281, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Sang-froid","Maîtrise de soi"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Diplomatie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"L''épice doit couler."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":6,"maxime":""}],"drive":null,"traits":["Agent de la Guilde","Diplomate"],"talents":[{"name":"Embarquement prioritaire","text":"Le PNJ échappe aux contrôles douaniers à bord des vaisseaux de la Guilde."}],"atouts":[{"name":"Contacts dans la Guilde","quality":null},{"name":"Bouclier, personnel","quality":null},{"name":"Contrat d''approvisionnement","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Agent de la Guilde' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Guérisseur', 'Médecin, chirurgien ou guérisseur', 'Dans un univers de batailles et de duels, les guérisseurs sont très demandés : chaque Maison a son conseiller médical, et on en trouve du médecin de combat au rebouteux de campagne. Les docteurs de l''École Suk, reconnaissables au losange tatoué sur leur front, sont les plus prestigieux et les plus chers.', '["Notable", "Archétype"]', 'Livre de base', 282, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Médecine d''urgence","Chirurgie"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Sang-froid"]},{"key":"mobilite","rang":6,"specialisations":[]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":7,"maxime":"Une dure vérité vaut mieux qu''un doux mensonge."}],"drive":null,"traits":["Guérisseur"],"talents":[{"name":"Étude poussée","text":"Une fois par scène, Le PNJ peut utiliser sa compétence d''Analyse sur un test à la place de toute autre compétence ; il est considéré comme disposant d''une spécialisation pour ce test."}],"atouts":[{"name":"Brilleur","quality":null},{"name":"Dossiers médicaux","quality":null},{"name":"Trousse médicale","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Guérisseur' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Soldat / Garde de Maison', 'Soldat ou garde au service d''une Maison', 'Chaque Maison a besoin de soldats et de gardes pour protéger sa résidence et tenir la ligne de front en temps de guerre. Fidèles et loyaux, ils restent humains, avec des faiblesses qu''un ennemi rusé peut exploiter.', '["Notable", "Archétype"]', 'Livre de base', 283, '{"rank":"notable","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":6,"specialisations":["Laser","Tactique"]},{"key":"discipline","rang":5,"specialisations":["Sang-froid"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":"Je n''abandonne jamais mon poste."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Militaire"],"talents":[{"name":"Indéfectible loyauté","text":"Au début de chaque aventure où il apparaît, le PNJ dispose de 3 points de Menace (1 Détermination) que lui seul peut utiliser, uniquement pour une action au service direct de sa Maison."}],"atouts":[{"name":"Conscrits","quality":null},{"name":"Laser","quality":null},{"name":"Habilitation de sécurité","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Soldat / Garde de Maison' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Mentat', 'Ordinateur humain, conseiller et stratège', 'Les Mentats ont remplacé les machines pensantes : conditionnés en ordinateurs humains, réputés honnêtes, ils servent de stratèges, d''administrateurs, de conseillers politiques et de précepteurs. Beaucoup boivent du jus de sapho, qui leur teinte les lèvres de rouge.', '["Notable", "Archétype", "Mentat"]', 'Livre de base', 284, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Analyse de données","Raisonnement déductif"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":4,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Diplomatie"]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":7,"maxime":"Il y a toujours une raison."}],"drive":null,"traits":["Mentat","Conseiller politique"],"talents":[{"name":"Discipline mentat","text":"Le PNJ ajoute deux réussites automatiques à tous les tests d''Analyse visant à se souvenir de faits ou de données."}],"atouts":[{"name":"Accès aux données de l''employeur","quality":null},{"name":"Réseau d''informateurs","quality":null},{"name":"Sapho","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Mentat' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Marchand', 'Négociant fortuné d''Arrakis', 'Vêtus de riches étoffes et circulant en véhicule terrestre, les marchands tiennent l''essentiel du commerce légal d''Arrakis, des produits de luxe à l''eau. Courtiers plus que colporteurs, beaucoup ont des relations douteuses avec la CHOM ou les contrebandiers.', '["Notable", "Archétype"]', 'Livre de base', 285, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":["Analyse de données"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":4,"specialisations":[]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Marchandage","Persuasion"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":"Le pouvoir est dans les solaris."},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Courtier","Riche"],"talents":[{"name":"Déterminé","text":"Après avoir dépensé de la Menace pour obtenir un point de Détermination, le PNJ lance 1d20. Sur un résultat inférieur ou égal à sa Discipline seule, il regagne immédiatement la Menace dépensée."}],"atouts":[{"name":"Réseau d''information","quality":null},{"name":"Ornithoptère","quality":null},{"name":"Entrepôt","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Marchand' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Noble (jeune héritier)', 'Jeune héritier d''une Maison mineure', 'Malgré le luxe, les jeunes nobles mènent une vie incertaine : ils apprennent tôt à repérer un chercheur-tueur et à se méfier de leur assiette. Toujours en quête d''alliés et de moyens de surprendre leurs ennemis, ils ont des solaris pour arriver à leurs fins.', '["Notable", "Archétype"]', 'Livre de base', 286, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Commandement","Sang-froid"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Diplomatie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je suis né pour diriger."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Noble","Maison mineure"],"talents":[{"name":"Audacieux (Rhétorique)","text":"Le PNJ peut relancer un d20 obtenu en dépensant de la Menace lors d''un test de Rhétorique."}],"atouts":[{"name":"Influence","quality":null},{"name":"Kindjal","quality":null},{"name":"Ornithoptère","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Noble (jeune héritier)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Noble (vétéran)', 'Noble aguerri d''une Maison', 'Ceux qui survivent aux jeux mortels de la politique deviennent de redoutables adversaires, avec la puissance d''une Maison à leur service. Un noble vétéran ne vient sur Arrakis que pour des affaires trop secrètes pour un émissaire, et voyage rarement seul.', '["Notable", "Archétype"]', 'Livre de base', 287, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Politique des Maisons","Kanly"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Diplomatie"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":"Possession vaut titre."},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":6,"maxime":""}],"drive":null,"traits":["Noble"],"talents":[{"name":"La théorie en pratique","text":"Une fois par scène, quand Le PNJ Obtient des informations, il peut créer gratuitement un trait représentant un avantage identifié grâce aux informations reçues."}],"atouts":[{"name":"Gardes du corps","quality":null},{"name":"Kindjal gravé aux armes de la Maison","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Noble (vétéran)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Sardaukar', 'Soldat d''élite de l''Empereur', 'Force d''élite loyale au seul Empereur Padishah, forgée par un entraînement secret sur la planète-prison de Salusa Secundus, d''une brutalité et d''un mépris du danger suicidaires. La simple menace de leur déploiement suffit à faire plier une Maison. Leur équipement dépend de leur mission, avec souvent des armes dissimulées.', '["Notable", "Archétype", "Corrino"]', 'Livre de base', 288, '{"rank":"notable","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":8,"specialisations":["Laser","Lames longues","Lames courtes","Tactique"]},{"key":"discipline","rang":7,"specialisations":["Maîtrise de soi"]},{"key":"mobilite","rang":7,"specialisations":["Rapidité"]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":8,"maxime":"Mon couteau n''est jamais au fourreau."},{"key":"domination","rang":6,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Sardaukar","Soldat"],"talents":[{"name":"Soutien","text":"Le PNJ peut dépenser 2 points de Menace pour permettre à un allié de relancer sa réserve de dés. L''allié peut aussi utiliser la Discipline du Sardaukar à la place de sa compétence."},{"name":"Action décisive","text":"Après avoir éliminé un atout ennemi grâce au Combat, Le PNJ peut éliminer un second atout ennemi en dépensant 2 points de Menace."},{"name":"Maître d''armes","text":"Au début d''un duel, d''une escarmouche ou d''une bataille, Le PNJ peut dépenser 1 point de Menace pour augmenter de 1 la Qualité d''un de ses atouts martiaux pour la durée du conflit."}],"atouts":[{"name":"Laser","quality":null},{"name":"Garrot de shigavrille","quality":null},{"name":"Bouclier","quality":null},{"name":"Kindjal","quality":null},{"name":"Fléchette","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Sardaukar' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Scientifique', 'Chercheur au service d''une Maison ou d''un commanditaire', 'Des chimistes aux ingénieurs, les scientifiques changent le fonctionnement de l''Imperium. Sur Arrakis, plusieurs Maisons ont des laboratoires secrets pour créer une source artificielle d''épice ou en améliorer la récolte. Rarement joueurs politiques, ils deviennent souvent des pions, jusqu''à l''enlèvement ou l''assassinat.', '["Notable", "Archétype"]', 'Livre de base', 289, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Raisonnement déductif","Physique"]},{"key":"combat","rang":3,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Observation"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":7,"maxime":"La science résoudra le problème."}],"drive":null,"traits":["Chercheur"],"talents":[{"name":"Étude poussée","text":"Une fois par scène, Le PNJ peut utiliser sa compétence d''Analyse sur un test à la place de toute autre compétence ; il est considéré comme disposant d''une spécialisation pour ce test."}],"atouts":[{"name":"Bobines de shigavrille","quality":null},{"name":"Laboratoire","quality":null},{"name":"Données sur Arrakis","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Scientifique' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Domestique', 'Serviteur d''une Maison noble', 'Assistants, coursiers, cuisiniers, gardes, mécaniciens ou précepteurs, les domestiques assurent le quotidien d''une Maison sans qu''on les remarque. Observateurs, ils connaissent scandales et secrets, et beaucoup ont des loyautés extérieures : sietch, espions, contrebandiers ou assassins.', '["Notable", "Archétype"]', 'Livre de base', 290, '{"rank":"notable","competences":[{"key":"analyse","rang":4,"specialisations":["Étiquette"]},{"key":"combat","rang":3,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":5,"specialisations":["Écoute"]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":6,"maxime":"Ce qu''on souhaite voir vrai l''est rarement."}],"drive":null,"traits":["Domestique"],"talents":[{"name":"Agile","text":"Lors d''un test de Mobilité en terrain difficile, Le PNJ réduit la Difficulté de 2. Si elle tombe à 0, le PNJ franchit ou contourne librement l''obstacle."}],"atouts":[{"name":"Enregistrement illégal","quality":null},{"name":"Vieil ami","quality":null},{"name":"Accès de confiance","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Domestique' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Contrebandier', 'Trafiquant d''épice et de marchandises', 'Entre bases cachées du désert et vaisseaux en orbite basse, les contrebandiers fournissent de l''épice illégale à qui peut payer. Ils rejettent les structures de pouvoir de l''Imperium, la Maison régnante d''Arrakis et la tyrannie de la CHOM, et survivent par leur ingéniosité.', '["Notable", "Archétype", "Contrebandiers"]', 'Livre de base', 291, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":["Combat déloyal"]},{"key":"discipline","rang":3,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Pilotage","Discrétion"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":6,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":7,"maxime":"Ils ne nous contrôleront pas."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Contrebandier"],"talents":[{"name":"Toujours sur ses gardes","text":"Quand Le PNJ tente un test pour détecter un danger ou des ennemis cachés, la Difficulté diminue de 2 (minimum 0). De plus, une fois par scène, il peut augmenter de 2 le coût pour un adversaire de Garder l''initiative."}],"atouts":[{"name":"Base secrète","quality":null},{"name":"Pistolet maula","quality":null},{"name":"Ornithoptère","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Contrebandier' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Espion / Infiltré', 'Agent infiltré chez un rival', 'Celui qui obtient des informations sur un rival est précieux ; celui qui pénètre au cœur de la maisonnée ennemie vaut son poids d''épice. Sur Arrakis, la réussite est richement récompensée, mais l''échec ou la découverte sont souvent fatals.', '["Notable", "Archétype"]', 'Livre de base', 292, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Sens du danger","Pièges"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":7,"maxime":"La vérité est ce qu''on en fait."}],"drive":null,"traits":["Imposteur","Espion"],"talents":[{"name":"Examen hâtif","text":"Quand Le PNJ tente un test d''Analyse pour fouiller une zone, il peut dépenser 2 points de Menace pour réduire la Difficulté de 1 et diviser par deux le temps nécessaire."}],"atouts":[{"name":"Capuchon ciboire","quality":null},{"name":"Crochets de serrurier","quality":null},{"name":"Mémoarchive","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Espion / Infiltré' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Technicien', 'Mécanicien et bricoleur', 'Mécaniciens et bricoleurs maintiennent Arrakis en marche, capables de changer les pales d''un ornithoptère ou de désensabler un recycleur d''eau les yeux fermés. Sur cette planète brûlante, créativité et improvisation sont la clé de leur survie.', '["Notable", "Archétype"]', 'Livre de base', 293, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Technologie avancée","Raisonnement déductif"]},{"key":"combat","rang":3,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Précision"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":6,"maxime":"Mes compétences nous permettront de continuer à tourner."},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Technicien"],"talents":[{"name":"Contrôle rigoureux","text":"Le PNJ peut utiliser sa Discipline à la place de n''importe quelle compétence lors d''une tâche étendue. Si la compétence était déjà la Discipline, le PNJ gagne +1 aux conditions."}],"atouts":[{"name":"Accès technique","quality":null},{"name":"Outils","quality":null},{"name":"Lunettes de vision améliorée","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Technicien' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Maître tleilaxu', 'Maître du Bene Tleilax', 'Les Tleilaxu ont une apparence étrange (dents pointues, petite taille, teint grisâtre) qui met mal à l''aise, tout comme leurs services : organes artificiels, gholas, Danseurs-Visages. Les maîtres tleilaxu tirent parti de ce malaise.', '["Notable", "Archétype", "Bene Tleilax"]', 'Livre de base', 294, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Génétique","Savoir des factions (Tleilaxu)"]},{"key":"combat","rang":3,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Neurolinguistique"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":3,"maxime":""},{"key":"verite","rang":7,"maxime":"La science détient les réponses."}],"drive":null,"traits":["Tleilaxu","Biologiste"],"talents":[{"name":"Le parfait sous-entendu","text":"Le PNJ peut dissimuler un message caché dans une conversation en augmentant de 1 la Difficulté du test de Rhétorique."}],"atouts":[{"name":"Danseur-Visage","quality":null},{"name":"Enregistrement illégal","quality":null},{"name":"Amortisseur ixien","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Maître tleilaxu' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Porteur d''eau', 'Vendeur d''eau des rues d''Arrakeen', 'Reconnaissables à leur cri « Souk souk ! », les porteurs d''eau sillonnent Arrakeen. Certains s''enrichissent, mais la plupart achètent l''eau en gros à un marchand et la revendent avec une maigre marge ; ils ne manquent jamais de clients.', '["Notable", "Archétype"]', 'Livre de base', 295, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":2,"specialisations":[]},{"key":"discipline","rang":4,"specialisations":[]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Marchandage","Commérages"]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":6,"maxime":"Tout le monde veut de l''eau."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Porteur d''eau","Marchand"],"talents":[{"name":"Discours roué","text":"Le PNJ peut créer un nouveau trait chaque fois qu''il dépense de la Menace pour acheter des dés supplémentaires sur un test de Rhétorique."}],"atouts":[{"name":"Petite bande de nervis","quality":null},{"name":"Eau","quality":null},{"name":"Richesse","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Porteur d''eau' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Jaris', 'Obregon', 'Responsable des opérations d''épice du porteur Grief', 'Seconde surmenée du porteur Grief, fille illégitime d''un héritier de la Maison des personnages, reléguée au loin. Faussement effacée, rongée de rancœur et d''ambition, elle sabote la production pour un mystérieux « nouveau protecteur » : c''est la véritable méchante de l''aventure.', '["Notable", "Harvesters of Dune"]', 'Livre de base', 309, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Électronique","Mécanique"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Récolte de l''épice"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":7,"maxime":"J''obtiendrai ce qu''on me doit."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Ouvrière de l''épice","Administratrice"],"talents":[{"name":"Prudent (Analyse)","text":"Obregon peut relancer un d20 obtenu en dépensant de la Menace (lors d''un test d''Analyse)."}],"atouts":[{"name":"Pistolet maula","quality":null},{"name":"Seconde du porteur","quality":null},{"name":"Protecteur","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Obregon' AND COALESCE(prenom, '') = 'Jaris' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Lorrimer', 'Globus', 'Capitaine du porteur Grief', 'Bureaucrate arrivé au sommet de son incompétence, sans imagination, imbu de lui-même et paresseux : il laisse Obregon gérer le Grief. Sa méthode favorite consiste à trouver un bouc émissaire, le punir brutalement puis annoncer que le problème est réglé ; il supporte mal l''ingérence de sa hiérarchie.', '["Notable", "Harvesters of Dune"]', 'Livre de base', 311, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Récolte de l''épice"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Intimidation"]}],"principes":[{"key":"devoir","rang":6,"maxime":""},{"key":"domination","rang":7,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":"Un commandant doit être obéi."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Commandant de porteur","Impopulaire"],"talents":[{"name":"Toujours sur ses gardes","text":"Quand Globus tente un test pour détecter un danger ou des ennemis cachés, la Difficulté diminue de 2 (minimum 0). De plus, une fois par scène, il peut augmenter de 2 le coût pour un adversaire de Garder l''initiative."}],"atouts":[{"name":"Commandant de porteur","quality":null},{"name":"Couteau","quality":null},{"name":"Serviteur de la Résidence","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Globus' AND COALESCE(prenom, '') = 'Lorrimer' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Taryn', 'Jellicoe', 'Pilote d''ornithoptère', 'Pilote d''ornithoptère du porteur Graf Von Dreissen (ou de la Maison des personnages), née sur Arrakis, avec des notions de survie dans le désert. Peut-être une Fremen qui jauge les personnages ; honnête, très pragmatique et peu bavarde.', '["Notable", "Harvesters of Dune"]', 'Livre de base', 313, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Survie (désert)"]},{"key":"mobilite","rang":7,"specialisations":["Pilotage (ornithoptère)"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je couvre les arrières de ceux qui couvrent les miens."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Pilote","Native d''Arrakis"],"talents":[],"atouts":[{"name":"Couteau","quality":null},{"name":"Ornithoptère","quality":null},{"name":"Distille","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Jellicoe' AND COALESCE(prenom, '') = 'Taryn' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Drasil', 'Chef d''une petite bande de Fremen', 'Chef d''une petite bande de Fremen du désert, méfiant envers les étrangers et blessé par de récents heurts avec la Maison des personnages. Fier, il n''offre pas facilement son amitié mais reste curieux de ces étrangers ; il échange les maigres réserves d''épice de sa bande avec des contrebandiers.', '["Notable", "Harvesters of Dune", "Fremen"]', 'Livre de base', 313, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames courtes"]},{"key":"discipline","rang":8,"specialisations":["Commandement","Survie (désert)"]},{"key":"mobilite","rang":7,"specialisations":["Chevaucheur de ver"]},{"key":"rhetorique","rang":6,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Le désert prend ce qui lui est dû."},{"key":"justice","rang":6,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Fremen","Méfiant"],"talents":[{"name":"Ténacité (Combat)","text":"Drasil peut Résister à la défaite deux fois par scène lors d''un conflit utilisant la compétence Combat."}],"atouts":[{"name":"Krys","quality":null},{"name":"Chef fremen","quality":null},{"name":"Fremkit","quality":null},{"name":"Distille","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Drasil' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Jothi', 'Metzos', 'Capitaine de la moissonneuse Alberich', 'Patronne brutale de la moissonneuse Alberich, grande, grossière et pas effrayée par la bagarre. Elle détourne de l''épice brute pour la revendre et partage assez avec l''équipage pour acheter son silence. Directe et sans ruse, elle est avide et peut être achetée ou intimidée par plus coriace qu''elle.', '["Notable", "Harvesters of Dune"]', 'Livre de base', 315, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":[]},{"key":"combat","rang":7,"specialisations":[]},{"key":"discipline","rang":8,"specialisations":["Récolte de l''épice"]},{"key":"mobilite","rang":7,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":"Tout le monde a ses petites combines."},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Ouvrière de l''épice","Capitaine"],"talents":[{"name":"Chercher les ennuis","text":"Metzos peut contacter la pègre."}],"atouts":[{"name":"Pistolet maula","quality":null},{"name":"Capitaine de moissonneuse","quality":null},{"name":"Contacts criminels","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Metzos' AND COALESCE(prenom, '') = 'Jothi' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Corinth', 'Euler', 'Mécanicien de la moissonneuse Alberich', 'Mécanicien compétent de l''industrie de l''épice, jamais promu à cause de son caractère revêche et de son manque de respect envers ses supérieurs. Indifférent au trafic de Metzos mais hostile à la Maison, il prend sa part et se tait ; il devient franchement hostile si on l''accuse de sabotage ou d''incompétence.', '["Notable", "Harvesters of Dune"]', 'Livre de base', 316, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Survie (désert)"]},{"key":"mobilite","rang":7,"specialisations":["Pilotage (ornithoptère)"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je couvre les arrières de ceux qui couvrent les miens."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Mécanicien","Travailleur acharné"],"talents":[{"name":"Dévouement","text":"S''il n''y a pas de Menace au début d''une scène, Euler peut lancer 1d20 : sur un résultat inférieur à sa Discipline, il ajoute 1 point de Menace."}],"atouts":[{"name":"Trousse à outils","quality":null},{"name":"Couteau","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Euler' AND COALESCE(prenom, '') = 'Corinth' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Équipage de l''Alberich', 'Groupe d''ouvriers de la moissonneuse', 'Rude équipe de récolteurs habitués à la moissonneuse bruyante et exiguë, des pyons citadins qui méprisent et craignent les Fremen. Complices du trafic de Metzos, ils savent que la révélation pourrait leur coûter la vie et ne se battent contre les personnages que poussés par Metzos ou Obregon.', '["Mineur", "Harvesters of Dune"]', 'Livre de base', 316, '{"rank":"minor","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":["Récolte de l''épice"]},{"key":"mobilite","rang":6,"specialisations":[]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":4,"traits":["Ouvriers de l''épice"],"talents":[],"atouts":[{"name":"Outils","quality":null},{"name":"Couteau","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Équipage de l''Alberich' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Livre de base');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Wyr', 'Jadrel', 'Cheffe des contrebandiers du Sand Boulder', 'Elle dirige l''entrepôt de la base contrebandière du Sand Boulder, une ancienne station d''essai impériale enfouie dans le désert, et veille à ce que personne n''emporte ce qui ne lui revient pas. Rapide avec son pistolet maula, elle est respectée de toutes les factions de contrebandiers d''Arrakis.', '["Notable", "Contrebandiers", "Sand Boulder"]', 'GM Toolkit', 29, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Rapidité"]},{"key":"rhetorique","rang":7,"specialisations":["Charme"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je dois tout aux contrebandiers."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":6,"maxime":"La vérité est dans les registres."}],"drive":null,"traits":["Contrebandière","Administratrice"],"talents":[{"name":"Impérieux","text":"Une fois par scène, Wyr peut accorder une action supplémentaire à un allié pendant son tour."}],"atouts":[{"name":"Pistolet maula","quality":null},{"name":"Bobines de shigavrille (registres)","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Jadrel' AND COALESCE(prenom, '') = 'Wyr' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Brae', 'Oroys', 'Receleur persuasif du Sand Boulder', 'Il tient le comptoir du Sand Boulder, bar et magasin des contrebandiers, et se vante d''avoir tout ce qu''un contrebandier peut désirer : alcool maison, sémuta, épice illicite, goûte-poison, distilles. Il pratique un troc strict et n''hésite pas à mettre à prix la tête d''un mauvais payeur.', '["Notable", "Contrebandiers", "Sand Boulder"]', 'GM Toolkit', 30, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Résolution"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Persuasion"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":"Se préparer, c''est être fort."},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":6,"maxime":"La justice est brutale."},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Contrebandier","Commerçant"],"talents":[{"name":"Déterminé","text":"Après la dépense d''un point de Détermination, lancez 1d20. Sur un résultat inférieur ou égal à la Discipline seule de Brae, le meneur récupère immédiatement les 3 points de Menace dépensés pour ce point de Détermination."}],"atouts":[{"name":"Alcool","quality":null},{"name":"Bracelet à fléchettes","quality":null},{"name":"Dettes qu''on lui doit","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Oroys' AND COALESCE(prenom, '') = 'Brae' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Yari', 'Elenne', 'Ingénieure de maintenance et scientifique du Sand Boulder', 'Elle gère les laboratoires du Sand Boulder, masquée et en lourd tablier, au milieu des poisons, drogues, armes nouvelles et moteurs. Scientifique et ingénieure d''une curiosité intense et d''un savoir étendu, elle expérimente sur n''importe quoi pour quelques solaris.', '["Notable", "Contrebandiers", "Sand Boulder"]', 'GM Toolkit', 30, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Technologie avancée"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":4,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Grâce"]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":6,"maxime":"On peut créer la puissance par l''expérimentation."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":7,"maxime":"La science nous montre ce qui est réel."}],"drive":null,"traits":["Contrebandière","Scientifique","Ingénieure"],"talents":[{"name":"Étude poussée","text":"Une fois par scène, Yari peut utiliser sa compétence d''Analyse sur un test à la place de toute autre compétence ; elle est considéré comme disposant d''une spécialisation pour ce test."}],"atouts":[{"name":"Bague à fléchette","quality":null},{"name":"Analyseur chimique portatif","quality":null},{"name":"Bobine de shigavrille (détails et résultats d''expériences)","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Elenne' AND COALESCE(prenom, '') = 'Yari' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Brewen', 'Ayd', 'Pilote d''ornithoptère contrebandier', 'Audacieux et intrépide jusqu''à l''imprudence, contrebandier et pilote doué pour échapper aux autorités locales comme impériales. Toujours endetté auprès de Brae, il reste le pilote favori des contrebandiers de la région.', '["Notable", "Contrebandiers", "Sand Boulder"]', 'GM Toolkit', 31, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":6,"specialisations":["Stratégie"]},{"key":"discipline","rang":4,"specialisations":[]},{"key":"mobilite","rang":7,"specialisations":["Pilotage (ornithoptère)"]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":7,"maxime":"Ensemble, nous sommes puissants."},{"key":"foi","rang":6,"maxime":"Avec une paire d''ailes, je peux tout faire."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Contrebandier","Pilote"],"talents":[{"name":"Audacieux (Combat)","text":"Brewen peut relancer un d20 obtenu en ajoutant de l''Impulsion (de la Menace)."}],"atouts":[{"name":"Ornithoptère","quality":null},{"name":"Dette envers Brae","quality":null},{"name":"Pistolet maula","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ayd' AND COALESCE(prenom, '') = 'Brewen' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Tirenna', 'Kraic', 'Femme d''affaires impitoyable, maîtresse de la Maison d''Amaranth', 'Ancienne courtisane formée aux techniques du Bene Gesserit, elle dirige la Maison d''Amaranth, maison d''escortes d''Arrakeen devenue officine de renseignement, d''espionnage et de contrebande. Femme froide et séduisante, elle sait percer les désirs profonds de ses clients et les fiche tous.', '["Notable", "Maison d''Amaranth"]', 'GM Toolkit', 33, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Observation","Maîtrise de soi"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Charme","Sous-entendus"]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":"Plus que l''eau, le pouvoir est la vraie force sur Arrakis."},{"key":"foi","rang":6,"maxime":"Les gens sont mus par des instincts primaires que l''on peut exploiter."},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Femme d''affaires","Impitoyable"],"talents":[{"name":"Discours roué","text":"Tirenna peut créer un nouveau trait chaque fois que de la Menace est dépensée pour des dés supplémentaires sur un test de Rhétorique."}],"atouts":[{"name":"Systèmes de sécurité et de surveillance","quality":null},{"name":"Aiguille empoisonnée","quality":null},{"name":"Enregistrements vidéo et audio de clients notables","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Kraic' AND COALESCE(prenom, '') = 'Tirenna' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Rodikar', 'Garde du corps taciturne de la Maison d''Amaranth', 'Chef de la sécurité de la Maison d''Amaranth, chauve, discret, vêtu d''un costume sombre presque militaire ; son allure trahit une formation militaire ou mentat. Une de ses oreilles a été remplacée par un disque de métal. Il porte un bouclier personnel, un pistolet maula dissimulé et un kindjal affûté.', '["Notable", "Maison d''Amaranth"]', 'GM Toolkit', 33, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Combat déloyal","Combat à mains nues"]},{"key":"discipline","rang":6,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":["Sang-froid","Résolution"]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"La Maison d''Amaranth est une Maison bien suffisante pour moi."},{"key":"domination","rang":6,"maxime":"Je choisis les ordres auxquels j''obéis."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Videur","Mortel"],"talents":[{"name":"Toujours sur ses gardes","text":"Quand Rodikar tente un test pour détecter un danger ou des ennemis cachés, la Difficulté diminue de 2 (minimum 0). De plus, une fois par scène, il peut augmenter de 2 le coût pour un adversaire de Garder l''initiative."}],"atouts":[{"name":"Armure corporelle dissimulée","quality":null},{"name":"Pistolet maula","quality":null},{"name":"Kindjal","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Rodikar' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Gabin', 'Doresh', 'Chef steward de la Maison Wayku à bord du Star Princess', 'Chef steward du paquebot Star Princess. Officiellement chargé du confort des passagers, il veille surtout à ce que personne ne fâche la Guilde spatiale, et fera le nécessaire pour étouffer les ennuis avant qu''ils commencent.', '["Notable", "Maison Wayku", "Star Princess"]', 'GM Toolkit', 35, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Étiquette"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Charme","Empathie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je sers la Guilde en servant ma Maison."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":6,"maxime":"Les gens mentent toujours pour obtenir ce qu''ils veulent."}],"drive":null,"traits":["Steward","Poli"],"talents":[{"name":"Intentions cachées","text":"Quand un adversaire rate un test d''Analyse ou de Rhétorique contre Gabin, le PNJ peut immédiatement créer un trait reflétant une idée erronée que cet adversaire se fait à son sujet."}],"atouts":[{"name":"Listes de passagers","quality":null},{"name":"Couteau dissimulé","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Doresh' AND COALESCE(prenom, '') = 'Gabin' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Moina', 'Jardine', 'Marchande ambulante de la Maison Wayku', 'Petite marchande qui vend friandises et en-cas aux passagers du Star Princess. Son vrai métier est courtière en informations : elle surprend nouvelles, rumeurs et secrets, même chez ceux qui se croient à l''abri, et sait repérer l''acheteur potentiel.', '["Notable", "Maison Wayku", "Star Princess"]', 'GM Toolkit', 35, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Étiquette","Politique impériale"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":7,"maxime":"Prends ce que tu peux à qui tu peux."},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":6,"maxime":"La vérité se vend au plus offrant."}],"drive":null,"traits":["Marchande","Cupide"],"talents":[{"name":"Le parfait sous-entendu","text":"Moina peut dissimuler un message caché dans une conversation en augmentant de 1 la Difficulté du test de Rhétorique."}],"atouts":[{"name":"Rumeurs utiles","quality":null},{"name":"Friandises et en-cas","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Jardine' AND COALESCE(prenom, '') = 'Moina' AND COALESCE(source, '') = 'GM Toolkit');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Niran', 'Rani', 'Conseiller militaire harkonnen, instructeur', 'Commandant sans fioritures, prêt à envoyer des soldats à la mort si nécessaire, couvert de cicatrices de nombreuses batailles. Il connaît les dangers de la guerre et n''accepte aucune demi-mesure de ses élèves.', '["Notable", "Agents of Dune", "Harkonnen"]', 'Agents of Dune', 21, '{"rank":"notable","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames courtes","Stratégie"]},{"key":"discipline","rang":6,"specialisations":["Commandement"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":6,"maxime":"Un soldat n''est rien sans un commandant."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":8,"maxime":"Le destin séparera les faibles des forts."},{"key":"justice","rang":7,"maxime":"La victoire donne raison."},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Soldat","Abrasif"],"talents":[{"name":"Conseiller (Combat)","text":"Quand Niran assiste un allié avec le Combat, cet allié peut relancer un d20 de sa réserve."}],"atouts":[{"name":"Couteau","quality":null},{"name":"Épée","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Rani' AND COALESCE(prenom, '') = 'Niran' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Turo', 'Imshel', 'Instructeur harkonnen', 'Grand, cultivé, élégant et charmant là où Niran est grossier et dur, Turo cache sous sa diplomatie un esprit acéré capable de démolir ses élèves ; il s''en sert surtout pour calmer Niran.', '["Notable", "Agents of Dune", "Harkonnen"]', 'Agents of Dune', 22, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":["Psychiatrie"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":["Observation"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Charme"]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":8,"maxime":"Les élèves de l''an dernier sont les contacts de l''an prochain."},{"key":"foi","rang":7,"maxime":"Croyez en vos élèves et ils apprendront."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":6,"maxime":"Les mensonges ne nous apprennent rien."}],"drive":null,"traits":["Enseignant","Mondain"],"talents":[{"name":"Intentions cachées","text":"Quand un adversaire rate un test d''Analyse ou de Rhétorique contre Turo, le PNJ peut immédiatement créer un trait reflétant une idée erronée que cet adversaire se fait à son sujet."}],"atouts":[{"name":"Notes de formation","quality":null},{"name":"Couteau","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Imshel' AND COALESCE(prenom, '') = 'Turo' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Korbus', 'Zaan', 'Mentat harkonnen', 'Mentat distant qui observe pour calculer des données impartiales ; même la vie et la mort ne sont pour lui que des statistiques. Totalement loyal aux Harkonnen, c''est le véritable méchant de la campagne : sur ordre du Baron, il intrigue pour faire tomber la Maison Nagara.', '["Notable", "Agents of Dune", "Harkonnen", "Mentat"]', 'Agents of Dune', 22, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Analyse de données"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Maîtrise de soi"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Les Harkonnen récompenseront les fidèles."},{"key":"domination","rang":8,"maxime":"Le pouvoir est la seule vérité."},{"key":"foi","rang":6,"maxime":"Le destin a un rôle pour chacun de nous."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Mentat","Harkonnen","Fourbe"],"talents":[{"name":"Analyse projective","text":"Zaan peut méditer quelques minutes pour prédire l''avenir : test d''Analyse de Difficulté 4. En cas de réussite, le meneur peut considérer que Zaan sait quelle sera la prochaine action des personnages joueurs."},{"name":"Discipline mentat","text":"Zaan a une mémoire presque parfaite, même pour les données les plus complexes. Lors d''un test d''Analyse visant à se souvenir de données, l''un des d20 de sa réserve est considéré comme ayant fait 1 au lieu d''être lancé."}],"atouts":[{"name":"Faveur du baron Harkonnen","quality":null},{"name":"Lame dissimulée","quality":null},{"name":"Bouclier, personnel","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Zaan' AND COALESCE(prenom, '') = 'Korbus' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Sabrya', 'Zavr', 'Négociatrice de la CHOM', 'Diplomate expérimentée qui, malgré son goût du style et des usages de cour, est une femme d''affaires coriace. Elle respecte les personnages en tant que nobles mais les juge inexpérimentés et naïfs. Lors de tous ses tests, elle utilise son principe de Domination si elle le peut.', '["Notable", "Agents of Dune", "CHOM"]', 'Agents of Dune', 45, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":[]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Négociation"]}],"principes":[{"key":"devoir","rang":7,"maxime":""},{"key":"domination","rang":8,"maxime":"Seule la victoire compte."},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Diplomate","Arrogante"],"talents":[{"name":"Dévouement","text":"S''il n''y a pas de Menace au début d''une scène, Sabrya peut lancer 1d20 : sur un résultat inférieur à sa Discipline, elle ajoute 1 point de Menace."}],"atouts":[{"name":"Influence de la CHOM","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Zavr' AND COALESCE(prenom, '') = 'Sabrya' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Kira', 'Jaro', 'Technicienne de laboratoire', 'Agente correcte et technicienne, elle a choisi le mauvais camp : elle hait les Harkonnen et sait que sa seule chance de survie est de se fier à la Maison Nagara et d''implorer sa protection. En duel, elle utilise la Domination, ou la Foi si son adversaire n''a pas de bouclier.', '["Notable", "Agents of Dune"]', 'Agents of Dune', 59, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Technologie avancée"]},{"key":"combat","rang":5,"specialisations":["Lames courtes"]},{"key":"discipline","rang":6,"specialisations":[]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Je couvre les arrières de ceux qui couvrent les miens."},{"key":"domination","rang":8,"maxime":"Personne ne t''aidera, à part toi-même."},{"key":"foi","rang":6,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Technicienne","Arrogante"],"talents":[],"atouts":[{"name":"Kindjal","quality":null},{"name":"Aiguille empoisonnée","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Jaro' AND COALESCE(prenom, '') = 'Kira' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Asham', 'Perro', 'Juge du Changement, arbitre des opérations sur Arrakis', 'Ancien envoyé de la Guilde spatiale sur Arrakis, nommé par l''Empereur Juge du Changement pour superviser le retrait des Harkonnen au profit de la Maison Nagara. Consciencieux et équitable, il soupçonne les Harkonnen d''œuvrer contre Nagara après avoir enquêté sur des sabotages d''équipement.', '["Notable", "Agents of Dune", "Guilde spatiale"]', 'Agents of Dune', 77, '{"rank":"notable","competences":[{"key":"analyse","rang":7,"specialisations":["Analyse de données"]},{"key":"combat","rang":4,"specialisations":["Combat à mains nues"]},{"key":"discipline","rang":6,"specialisations":["Maîtrise de soi"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":8,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":8,"maxime":"L''épice doit couler."},{"key":"domination","rang":6,"maxime":"Le commerce est un pouvoir exercé pour le profit."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":7,"maxime":"La vérité n''est jamais ambiguë."}],"drive":null,"traits":["Guilde spatiale","Juge du Changement (arbitre des opérations sur Arrakis)","Perspicace et honorable"],"talents":[{"name":"Prudent (Analyse)","text":"Quand Perro fait un test d''Analyse et achète des d20 supplémentaires avec de la Menace, il peut relancer un d20 de cette réserve."},{"name":"Le calme dans la tempête (Discipline)","text":"Avant de lancer un test de Discipline, Perro peut dépenser 2 points de Menace pour réussir automatiquement. Il ne génère alors ni Impulsion ni Menace pour ce test."},{"name":"Discours roué (Rhétorique)","text":"Lors d''un test de Rhétorique face à un individu, Perro peut acheter un d20 supplémentaire en dépensant de la Menace et créer gratuitement un nouveau trait s''appliquant à cet individu."}],"atouts":[{"name":"Réseau d''espions, d''informateurs et de techniciens de surveillance de la Guilde spatiale","quality":null},{"name":"Goûte-poison","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Perro' AND COALESCE(prenom, '') = 'Asham' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Roj', 'Varis', 'Major de la garde de la Maison Nagara', 'L''un des officiers les plus anciens et expérimentés de la Maison Nagara et le plus fidèle de la Comtesse. Plus tout jeune, il reste un combattant redoutable et un stratège rusé.', '["Notable", "Agents of Dune", "Nagara"]', 'Agents of Dune', 84, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames longues","Tactique"]},{"key":"discipline","rang":6,"specialisations":["Commandement"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":"Dans le service réside l''honneur."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":6,"maxime":"Ma Maison est juste."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Diplomate","Arrogant"],"talents":[{"name":"Action décisive (Combat)","text":"En conflit, quand Varis dépense de la Menace et élimine un atout adverse, il peut dépenser 2 points de Menace pour en éliminer un second."}],"atouts":[{"name":"Entraînement militaire","quality":null},{"name":"Pistolet maula","quality":null},{"name":"Épée","quality":null},{"name":"Kindjal","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Varis' AND COALESCE(prenom, '') = 'Roj' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Taras', 'Nikula', 'Capitaine de la garnison harkonnen d''Arrakeen', 'Jeune officier pressé de faire ses preuves, monté rapidement dans les rangs harkonnen par la fourberie et une efficacité brutale.', '["Notable", "Agents of Dune", "Harkonnen"]', 'Agents of Dune', 84, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":[]},{"key":"combat","rang":4,"specialisations":["Fusil"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Interrogatoire"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Par la seule volonté je m''élève."},{"key":"domination","rang":6,"maxime":"Les faibles sont nés pour servir."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Diplomate","Arrogant"],"talents":[{"name":"Action décisive (Combat)","text":"En conflit, quand Nikula dépense de la Menace et élimine un atout adverse, il peut dépenser 2 points de Menace pour en éliminer un second."},{"name":"Déterminé","text":"Après avoir dépensé 2 points de Menace (comme Détermination), Nikula peut lancer 1d20. Sur un résultat inférieur ou égal à sa Discipline, la Menace retourne immédiatement à la réserve."},{"name":"La lame lente","text":"Quand il attaque avec une arme de corps à corps en dépensant de la Menace, Nikula peut choisir un atout ennemi de sa zone, qui est ignoré."}],"atouts":[{"name":"Entraînement militaire","quality":null},{"name":"Pistolet maula","quality":null},{"name":"Kindjal","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Nikula' AND COALESCE(prenom, '') = 'Taras' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Soldats de Maison', 'Gardes de Nagara, de Harkonnen ou de Perro', 'La garde de la Maison Nagara, celle de la Maison Harkonnen et les gardes du corps de Perro ont le même entraînement : ce profil sert pour tous. Pour le principe, ils utilisent une valeur générique de 5.', '["Mineur", "Agents of Dune"]', 'Agents of Dune', 85, '{"rank":"minor","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":6,"specialisations":["Lames longues"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":5,"maxime":""},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":""}],"drive":5,"traits":["Soldats","Loyaux"],"talents":[],"atouts":[{"name":"Entraînement militaire","quality":null},{"name":"Pistolet maula","quality":null},{"name":"Épée","quality":null},{"name":"Kindjal","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Soldats de Maison' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Combattants fedaykin', 'Commandos de la mort fremen', 'Les Fedaykin sont d''ordinaire absolument mortels, mais ici ils se battent en deçà de leurs capacités car ils ont un autre plan. Pour tout principe, ils utilisent une valeur générique de 7.', '["Mineur", "Agents of Dune", "Fremen"]', 'Agents of Dune', 85, '{"rank":"minor","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":6,"specialisations":["Combat au couteau"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":4,"specialisations":[]}],"principes":[{"key":"devoir","rang":7,"maxime":""},{"key":"domination","rang":7,"maxime":""},{"key":"foi","rang":7,"maxime":""},{"key":"justice","rang":7,"maxime":""},{"key":"verite","rang":7,"maxime":""}],"drive":7,"traits":[],"talents":[],"atouts":[{"name":"Krys","quality":null},{"name":"Pistolets maula","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Combattants fedaykin' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Vadim', 'Saarela', 'Maître espion harkonnen sur Arrakis', 'Trapu, aux cheveux d''un roux vif, toujours un peu trop content de lui ; sa politesse semble n''être qu''un masque. Il sait que les Harkonnen complotent contre Nagara et veut savoir si les personnages font encore confiance à la Maison Harkonnen.', '["Notable", "Agents of Dune", "Harkonnen"]', 'Agents of Dune', 87, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Raisonnement déductif"]},{"key":"combat","rang":5,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Résolution"]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":7,"specialisations":["Interrogatoire"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Ma Maison avant tout."},{"key":"domination","rang":6,"maxime":"La sécurité s''obtient par l''exercice du pouvoir."},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":5,"maxime":"Ta vérité est malléable ; la mienne est absolue."}],"drive":null,"traits":["Espion","Cerveau"],"talents":[{"name":"Impérieux","text":"Saarela peut ordonner automatiquement à un allié ou subordonné d''agir pendant son tour, même si cet allié a déjà agi lors du round précédent ; l''allié peut agir plus tard dans le round à son propre tour. Saarela peut l''aider dans cette action."},{"name":"Observation passive","text":"Une fois par scène, Saarela apprend un détail significatif sur ce qu''il rencontre, s''il peut être déduit par l''observation."},{"name":"Discours roué (Rhétorique)","text":"Lors d''un test de Rhétorique face à un individu, Saarela peut acheter un d20 supplémentaire en dépensant de la Menace et créer gratuitement un nouveau trait s''appliquant à cet individu."}],"atouts":[{"name":"Pistolet maula","quality":null},{"name":"Kindjal","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Saarela' AND COALESCE(prenom, '') = 'Vadim' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Ustad', 'Turan', 'Auditeur de la CHOM pour l''épice', 'Bien trop séduisant pour être pris au sérieux comme auditeur, élégant et charmeur ; riche et puissant, il rêve d''épouser un membre d''une Maison noble. Il veut une meilleure part des profits de l''épice pour la CHOM afin de monter dans ses rangs.', '["Notable", "Agents of Dune", "CHOM"]', 'Agents of Dune', 87, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Analyse de données"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":6,"specialisations":["Maîtrise de soi"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Charme"]}],"principes":[{"key":"devoir","rang":7,"maxime":"La CHOM, c''est l''équilibre."},{"key":"domination","rang":5,"maxime":"Le pouvoir sans équilibre, c''est le chaos."},{"key":"foi","rang":5,"maxime":""},{"key":"justice","rang":6,"maxime":"Le balancier revient toujours."},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Auditeur de la CHOM","Curieux"],"talents":[{"name":"Étude poussée","text":"Une fois par scène, Turan peut utiliser l''Analyse à la place de toute autre compétence pour un test ; il est considéré comme disposant d''une spécialisation pour ce test."}],"atouts":[{"name":"Objectifs de la CHOM","quality":null},{"name":"Faveurs de la Maison Harkonnen","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Turan' AND COALESCE(prenom, '') = 'Ustad' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT 'Qadira Lariel', 'Narilan', 'Révérende Mère du Bene Gesserit', 'Pas si âgée, elle se fait passer pour plus vieille sous son voile afin d''être sous-estimée. Dévouée au Bene Gesserit et peu intéressée par la politique de l''épice, qu''elle feint de suivre, elle veut observer le nouveau dirigeant de la Maison Nagara et jauger l''impact de son règne sur la politique impériale.', '["Notable", "Agents of Dune", "Bene Gesserit"]', 'Agents of Dune', 88, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":[]},{"key":"combat","rang":6,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Observation"]},{"key":"mobilite","rang":5,"specialisations":["Grâce"]},{"key":"rhetorique","rang":5,"specialisations":["Empathie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"Nous protégeons les nôtres."},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":6,"maxime":"Tes Sœurs sont toujours derrière toi."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":8,"maxime":"La vérité se trouve dans les petites choses."}],"drive":null,"traits":["Révérende Mère du Bene Gesserit","Réservée","Fine et perspicace"],"talents":[{"name":"Hyperacuité","text":"La Révérende Mère Narilan peut dépenser 1 point de Menace pour recevoir deux informations sur une personne, un environnement ou une situation, qui ne sont pas immédiatement évidentes mais peuvent se déduire de l''observation."},{"name":"Mémoire seconde","text":"Héritière des souvenirs de toutes les Révérendes Mères de sa lignée, Narilan peut y faire appel quand ils sont utiles et obtient alors trois réussites automatiques."},{"name":"Entraînement prana-bindu","text":"Son entraînement lui donne un contrôle total de son corps : elle peut relancer un d20 lors d''un test de Mobilité ou de Discipline reposant sur ce contrôle."},{"name":"Voix","text":"Narilan peut dépenser 1 à 3 points de Menace pour obtenir autant de réussites automatiques sur un test de Rhétorique visant à influencer une cible. Plus les réussites sont nombreuses, plus l''usage de la Voix est flagrant. Elle peut aussi acheter des réussites automatiques pour résister à la Voix."}],"atouts":[{"name":"Couteau","quality":null},{"name":"Acolyte du Bene Gesserit","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Narilan' AND COALESCE(prenom, '') = 'Qadira Lariel' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Cenric', 'Envoyé de la Guilde spatiale sur Arrakis', 'Homme livresque, comptable et banquier compétent, vêtu simplement mais coûteusement, arborant fièrement l''emblème de la Guilde. Seule l''épice l''intéresse ; inquiet des attaques fremen, il veut savoir si les personnages sauront gérer les Fremen, par la diplomatie ou la force.', '["Notable", "Agents of Dune", "Guilde spatiale"]', 'Agents of Dune', 89, '{"rank":"notable","competences":[{"key":"analyse","rang":6,"specialisations":["Politique impériale"]},{"key":"combat","rang":4,"specialisations":[]},{"key":"discipline","rang":7,"specialisations":["Commandement"]},{"key":"mobilite","rang":4,"specialisations":[]},{"key":"rhetorique","rang":6,"specialisations":["Diplomatie"]}],"principes":[{"key":"devoir","rang":7,"maxime":"L''épice doit couler."},{"key":"domination","rang":7,"maxime":"La Guilde est le système artériel de l''univers. L''épice en est le sang."},{"key":"foi","rang":6,"maxime":"La Guilde est ce qui compte."},{"key":"justice","rang":5,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":null,"traits":["Envoyé","Guilde spatiale","Autoritaire et intellectuel"],"talents":[{"name":"Déterminé","text":"Après avoir dépensé 2 points de Menace (comme Détermination), Cenric peut lancer 1d20. Sur un résultat inférieur ou égal à sa Discipline, la Menace retourne immédiatement à la réserve."},{"name":"Discours roué (Rhétorique)","text":"Lors d''un test de Rhétorique face à un individu, Cenric peut acheter un d20 supplémentaire en dépensant de la Menace et créer gratuitement un nouveau trait s''appliquant à cet individu."}],"atouts":[{"name":"Intérêts de la Guilde spatiale","quality":null},{"name":"Exigences de la Guilde spatiale","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Cenric' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Harun', 'Guerrier fedaykin du sietch Jurf''ahmar', 'Jeune homme d''apparence banale mais totalement dévoué à sa tribu, prêt à mourir pour sa cause et pour vérifier si l''on peut faire confiance à la Maison Nagara.', '["Notable", "Agents of Dune", "Fremen"]', 'Agents of Dune', 97, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames courtes"]},{"key":"discipline","rang":6,"specialisations":["Maîtrise de soi"]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":6,"specialisations":["Duperie"]}],"principes":[{"key":"devoir","rang":6,"maxime":"Mon eau appartient à ma tribu."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Ne doute pas de la puissance de Dieu."},{"key":"justice","rang":6,"maxime":"Dans le sang, il y a la justice."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Guerrier fedaykin","Sietch Jurf''ahmar","Taciturne et stoïque"],"talents":[{"name":"La lame lente","text":"Quand il attaque avec une arme de corps à corps en dépensant de la Menace, Harun peut choisir un atout ennemi de sa zone, qui est ignoré."}],"atouts":[{"name":"Krys","quality":null},{"name":"Distille","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Harun' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Musa', 'Naib du sietch Jurf''ahmar', 'Chef pragmatique et expérimenté qui a mené sa tribu à travers bien des épreuves ; un peu âgé pour un Fremen, il ne craint pas encore d''être défié. Il accorde le bénéfice du doute aux inconnus mais les juge sur leurs actes, non sur leurs paroles.', '["Notable", "Agents of Dune", "Fremen"]', 'Agents of Dune', 104, '{"rank":"notable","competences":[{"key":"analyse","rang":5,"specialisations":[]},{"key":"combat","rang":7,"specialisations":["Lames courtes","Pistolets"]},{"key":"discipline","rang":6,"specialisations":["Maîtrise de soi"]},{"key":"mobilite","rang":6,"specialisations":["Discrétion"]},{"key":"rhetorique","rang":6,"specialisations":["Charme"]}],"principes":[{"key":"devoir","rang":8,"maxime":"Je dirige jusqu''à la mort."},{"key":"domination","rang":5,"maxime":""},{"key":"foi","rang":7,"maxime":"Arrakis est la Forge de Dieu."},{"key":"justice","rang":6,"maxime":"Le désert nous apprend à être justes."},{"key":"verite","rang":5,"maxime":""}],"drive":null,"traits":["Naib du sietch Jurf''ahmar","Guerrier fedaykin","Intense, intelligent et fier"],"talents":[{"name":"Conseiller (Rhétorique)","text":"Quand Musa assiste un allié avec la Rhétorique, il peut relancer 1d20 de la réserve de cet allié."},{"name":"Audacieux (Combat)","text":"Quand il achète des d20 supplémentaires avec de la Menace, Musa peut relancer un d20 de cette réserve."},{"name":"Le calme dans la tempête (Discipline)","text":"Avant de lancer un test de Discipline, Musa peut dépenser 2 points de Menace pour réussir automatiquement. Il ne génère alors ni Impulsion ni Menace pour ce test."}],"atouts":[{"name":"Pistolet maula","quality":null},{"name":"Krys","quality":null},{"name":"Distille","quality":null},{"name":"Cape jubba","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Musa' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Agents of Dune');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Contrebandiers (troupes harkonnen déguisées)', 'Soldats harkonnen se faisant passer pour des contrebandiers', 'Troupes harkonnen déguisées en contrebandiers, armées de lasers de fabrication ixienne.', '["Mineur", "Agents of Dune", "Harkonnen"]', 'Agents of Dune', 108, '{"rank":"minor","competences":[{"key":"analyse","rang":4,"specialisations":[]},{"key":"combat","rang":6,"specialisations":["Bagarre"]},{"key":"discipline","rang":5,"specialisations":[]},{"key":"mobilite","rang":5,"specialisations":[]},{"key":"rhetorique","rang":5,"specialisations":[]}],"principes":[{"key":"devoir","rang":4,"maxime":""},{"key":"domination","rang":4,"maxime":""},{"key":"foi","rang":4,"maxime":""},{"key":"justice","rang":4,"maxime":""},{"key":"verite","rang":4,"maxime":""}],"drive":4,"traits":["Soldat"],"talents":[],"atouts":[{"name":"Entraînement militaire","quality":null},{"name":"Laser ixien","quality":null},{"name":"Kindjal","quality":null}],"rolls":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Contrebandiers (troupes harkonnen déguisées)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Agents of Dune');
